function getRandomTeamForPosition(position, usedTeamDecades) {
    const decade = DECADES[Math.floor(Math.random() * DECADES.length)];
    const teamsInDecade = [...new Set(PLAYER_DB.filter(p => p.decade === decade).map(p => p.team))];
    const availableTeams = teamsInDecade.filter(t => !usedTeamDecades.includes(`${t}_${decade}`));
    if (availableTeams.length === 0) return getRandomTeamForPosition(position, usedTeamDecades);
    const team = availableTeams[Math.floor(Math.random() * availableTeams.length)];
    return { team, decade };
}
